import{_ as o,o as e,c as a,ag as s}from"./chunks/framework.DXGyWiRo.js";const g=JSON.parse('{"title":"导出到 Hoppscotch","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/export-hoppscotch.md","filePath":"zh/guide/export-hoppscotch.md","lastUpdated":1785990345000}'),r={name:"zh/guide/export-hoppscotch.md"};function p(c,t,h,n,d,i){return e(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="导出到-hoppscotch" tabindex="-1">导出到 Hoppscotch <a class="header-anchor" href="#导出到-hoppscotch" aria-label="Permalink to &quot;导出到 Hoppscotch&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Beta 功能</p><p>Hoppscotch 导出默认关闭，使用前请先在 <strong>Features</strong> 标签页中启用 <strong>Hoppscotch (Beta)</strong>。</p></div><p>EasyYapi 可以将 HTTP 接口导出为 Hoppscotch 集合。该渠道支持导出本地 JSON 文件，也支持上传到 Hoppscotch 服务端。</p><h2 id="启用渠道" tabindex="-1">启用渠道 <a class="header-anchor" href="#启用渠道" aria-label="Permalink to &quot;启用渠道&quot;">​</a></h2><p>打开 <strong>Settings</strong> &gt; <strong>Other Settings</strong> &gt; <strong>EasyApi</strong> &gt; <strong>Features</strong>，在 <strong>Export Channels</strong> 中启用 <strong>Hoppscotch (Beta)</strong>。</p><p>如果要上传云端，请打开 Hoppscotch 设置，通过浏览器登录或手动填写访问令牌。未配置令牌时，导出仍然会使用本地文件模式。</p><h2 id="导出集合" tabindex="-1">导出集合 <a class="header-anchor" href="#导出集合" aria-label="Permalink to &quot;导出集合&quot;">​</a></h2><ol><li>打开包含 API 的文件，或在 Project 视图中选择文件/文件夹。</li><li>选择 <strong>EasyYapi</strong> &gt; <strong>Export</strong> &gt; <strong>Hoppscotch (Beta)</strong>。</li><li>未登录时选择输出目录和文件名，默认文件为 <code>hoppscotch_collection.json</code>。</li><li>已登录时选择 <strong>(New) Create new collection</strong>，或选择已有集合进行更新。</li></ol><p>没有令牌时，生成的 JSON 可以手动导入 Hoppscotch。配置令牌后，EasyYapi 会通过 Hoppscotch API 上传集合。</p><h2 id="服务端和自托管设置" tabindex="-1">服务端和自托管设置 <a class="header-anchor" href="#服务端和自托管设置" aria-label="Permalink to &quot;服务端和自托管设置&quot;">​</a></h2><p>Hoppscotch 设置页提供以下选项：</p><table tabindex="0"><thead><tr><th>设置项</th><th>说明</th></tr></thead><tbody><tr><td><strong>Server URL</strong></td><td>Hoppscotch 服务地址，默认为 <code>https://hoppscotch.io</code>。</td></tr><tr><td><strong>Backend URL</strong></td><td>自托管部署使用的可选后端 API 地址。</td></tr><tr><td><strong>Login / Logout</strong></td><td>开始或清除浏览器登录会话。</td></tr><tr><td><strong>Manual Token</strong></td><td>浏览器登录不可用时使用的备用访问令牌。</td></tr></tbody></table><p>Hoppscotch 导出只支持 HTTP，不会将 gRPC 接口加入集合。</p><h2 id="更新已有集合" tabindex="-1">更新已有集合 <a class="header-anchor" href="#更新已有集合" aria-label="Permalink to &quot;更新已有集合&quot;">​</a></h2><p>更新集合采用先创建后删除的流程。EasyYapi 会先请求确认，因为替换后的集合会获得新的 ID；更新后指向旧集合的分享链接会失效。</p><h2 id="配置规则" tabindex="-1">配置规则 <a class="header-anchor" href="#配置规则" aria-label="Permalink to &quot;配置规则&quot;">​</a></h2><p>以下渠道规则可以自定义集合：</p><ul><li><code>hopp.host</code>：覆盖集合 Host</li><li><code>hopp.prerequest</code>、<code>hopp.class.prerequest</code>、<code>hopp.collection.prerequest</code>：分别添加接口、类、集合级别的请求前脚本</li><li><code>hopp.test</code>、<code>hopp.class.test</code>、<code>hopp.collection.test</code>：添加响应测试</li><li><code>hopp.format.after</code>：在集合格式化后执行</li></ul><p>详见<a href="/zh/settings/config-rule">配置规则</a>。</p>',19)])])}const u=o(r,[["render",p]]);export{g as __pageData,u as default};
